//! 記録してよいかの判定(機密フォーマット、除外アプリ、コピー元不明の扱い)。track-clipboard が実装する。
//! OS に触れない純粋な関数だけで構成し、形式の名前の一覧と値を受け取って判定する(ADR-002)。

use crate::domain::clip::AppRef;

/// この名前の形式があれば機密として記録しない(macOS)。
pub const SENSITIVE_FORMATS: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
    // Windows
    "ExcludeClipboardContentFromMonitorProcessing",
    "Clipboard Viewer Ignore",
];

/// 値が 0 のとき機密として扱う形式(Windows。DWORD の 0)。
pub const FORMAT_ZERO_MEANS_EXCLUDE: &str = "CanIncludeInClipboardHistory";

/// 記録しない理由。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SkipReason {
    SensitiveFormat,
    ExcludedApp,
    UnknownSource,
}

/// 記録してよいかの判定結果。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Decision {
    Record,
    Skip(SkipReason),
}

/// 機密の形式を含むか。`value_of` は形式名から値(バイト列)を引く。引けなければ `None`。
pub fn has_sensitive_format(
    formats: &[String],
    value_of: &dyn Fn(&str) -> Option<Vec<u8>>,
) -> bool {
    formats.iter().any(|f| {
        if SENSITIVE_FORMATS.iter().any(|s| s.eq_ignore_ascii_case(f)) {
            return true;
        }
        if f.eq_ignore_ascii_case(FORMAT_ZERO_MEANS_EXCLUDE) {
            // 値が読めない場合は機密とみなさない(値が 0 のときだけ除外する)
            return value_of(f).is_some_and(|v| !v.is_empty() && v.iter().all(|b| *b == 0));
        }
        false
    })
}

/// 記録してよいかを判定する。機密形式 > 除外アプリ > コピー元不明の順に見る。
pub fn decide(
    formats: &[String],
    value_of: &dyn Fn(&str) -> Option<Vec<u8>>,
    source: Option<&AppRef>,
    excluded_apps: &[AppRef],
    record_unknown_source: bool,
) -> Decision {
    if has_sensitive_format(formats, value_of) {
        return Decision::Skip(SkipReason::SensitiveFormat);
    }
    match source {
        Some(src) => {
            if excluded_apps
                .iter()
                .any(|a| a.id.eq_ignore_ascii_case(&src.id))
            {
                Decision::Skip(SkipReason::ExcludedApp)
            } else {
                Decision::Record
            }
        }
        None if record_unknown_source => Decision::Record,
        None => Decision::Skip(SkipReason::UnknownSource),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn none(_: &str) -> Option<Vec<u8>> {
        None
    }

    fn names(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    fn app(id: &str) -> AppRef {
        AppRef {
            id: id.to_string(),
            name: "ダミー".to_string(),
        }
    }

    #[test]
    fn macOSの機密型名を含むとき機密と判定する() {
        for name in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType",
            "com.agilebits.onepassword",
            "de.petermaurer.TransientPasteboardType",
            "com.typeit4me.clipping",
        ] {
            assert!(
                has_sensitive_format(&names(&["public.utf8-plain-text", name]), &none),
                "{name}"
            );
        }
    }

    #[test]
    fn Windowsの機密形式を含むとき機密と判定する() {
        assert!(has_sensitive_format(
            &names(&[
                "CF_UNICODETEXT",
                "ExcludeClipboardContentFromMonitorProcessing"
            ]),
            &none
        ));
        assert!(has_sensitive_format(
            &names(&["Clipboard Viewer Ignore"]),
            &none
        ));
    }

    #[test]
    fn 形式名の大文字小文字を区別しない() {
        assert!(has_sensitive_format(
            &names(&["ORG.NSPASTEBOARD.CONCEALEDTYPE"]),
            &none
        ));
    }

    #[test]
    fn CanIncludeInClipboardHistoryが0のとき機密と判定する() {
        let zero = |n: &str| (n == "CanIncludeInClipboardHistory").then(|| vec![0, 0, 0, 0]);
        assert!(has_sensitive_format(
            &names(&["CanIncludeInClipboardHistory"]),
            &zero
        ));
    }

    #[test]
    fn CanIncludeInClipboardHistoryが1のとき機密と判定しない() {
        let one = |n: &str| (n == "CanIncludeInClipboardHistory").then(|| vec![1, 0, 0, 0]);
        assert!(!has_sensitive_format(
            &names(&["CanIncludeInClipboardHistory"]),
            &one
        ));
    }

    #[test]
    fn CanIncludeInClipboardHistoryの値が読めないとき機密と判定しない() {
        assert!(!has_sensitive_format(
            &names(&["CanIncludeInClipboardHistory"]),
            &none
        ));
    }

    #[test]
    fn 通常の形式だけのとき機密と判定しない() {
        assert!(!has_sensitive_format(
            &names(&["public.utf8-plain-text", "public.html"]),
            &none
        ));
        assert!(!has_sensitive_format(&[], &none));
    }

    #[test]
    fn 機密形式があるとき記録しない() {
        let d = decide(
            &names(&["org.nspasteboard.ConcealedType"]),
            &none,
            Some(&app("com.example.app")),
            &[],
            true,
        );
        assert_eq!(d, Decision::Skip(SkipReason::SensitiveFormat));
    }

    #[test]
    fn コピー元が除外アプリのとき記録しない() {
        let d = decide(
            &names(&["public.utf8-plain-text"]),
            &none,
            Some(&app("com.1password.1password")),
            &[app("com.1password.1password")],
            true,
        );
        assert_eq!(d, Decision::Skip(SkipReason::ExcludedApp));
    }

    #[test]
    fn 除外アプリのidは大文字小文字を無視して比較する() {
        let d = decide(
            &names(&["public.utf8-plain-text"]),
            &none,
            Some(&app("BITWARDEN.EXE")),
            &[app("Bitwarden.exe")],
            true,
        );
        assert_eq!(d, Decision::Skip(SkipReason::ExcludedApp));
    }

    #[test]
    fn 除外アプリ以外のとき記録する() {
        let d = decide(
            &names(&["public.utf8-plain-text"]),
            &none,
            Some(&app("com.apple.Safari")),
            &[app("com.1password.1password")],
            false,
        );
        assert_eq!(d, Decision::Record);
    }

    #[test]
    fn コピー元不明で設定が記録のとき記録する() {
        let d = decide(&names(&["public.utf8-plain-text"]), &none, None, &[], true);
        assert_eq!(d, Decision::Record);
    }

    #[test]
    fn コピー元不明で設定が非記録のとき記録しない() {
        let d = decide(&names(&["public.utf8-plain-text"]), &none, None, &[], false);
        assert_eq!(d, Decision::Skip(SkipReason::UnknownSource));
    }
}
